    def __init__(self, model):
        if getattr(model, "dropout_probability", 0) <= 0:
            raise ValueError("model must have positive dropout_probability")
        if getattr(model, "mode", None) not in ("caption", "gesture"):
            raise ValueError("unsupported model mode")
        self.model = model

    @staticmethod
    def _validate(signal, metadata):
        if not isinstance(signal, (list, tuple)) or any(
            isinstance(value, bool) or not isinstance(value, (int, float))
            for value in signal
        ):
            raise TypeError("signal must be a numeric sequence")
        if not isinstance(metadata, dict):
            raise TypeError("metadata must be a dictionary")

    @staticmethod
    def _scale(value):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("scale must be numeric")
        return value

    def _invoke(self, signal, metadata):
        result = self.model(copy.deepcopy(signal), copy.copy(metadata))
        if not isinstance(result, (list, tuple)) or any(
            isinstance(value, bool) or not isinstance(value, (int, float))
            for value in result
        ):
            raise ValueError("model output must be numeric")
        return list(result)

    def _pair(self, signal, metadata):
        conditioned = self._invoke(signal, metadata)
        disabled_metadata = copy.deepcopy(metadata)
        disabled_metadata["disabled"] = True
        disabled = self._invoke(signal, disabled_metadata)
        if len(conditioned) != len(disabled):
            raise ValueError("model outputs must have equal lengths")
        return conditioned, disabled

    @staticmethod
    def _blend(conditioned, disabled, scale):
        return [u + scale * (c - u) for c, u in zip(conditioned, disabled)]

    def forward(self, signal, metadata):
