        masked = list(signal)
        indices = metadata.get("mask_indices", ())
        if not isinstance(indices, (list, tuple)):
            raise TypeError("mask_indices must be a sequence")
        for index in indices:
            if isinstance(index, bool) or not isinstance(index, int):
                raise TypeError("mask indices must be integers")
            if index < 0 or index >= len(masked):
                raise IndexError("mask index out of range")
            masked[index] = 0
        conditioned, disabled = self._pair(masked, metadata)
        return self._blend(conditioned, disabled, 1.8)

    def forward_mixed(self, signal, metadata):
        self._validate(signal, metadata)
        scale = self._scale(metadata.get("scale"))
